 public void attach(int id){if(session==id)return;release();if(id==0)return;session=id;try{capture=new Visualizer(id);capture.setCaptureSize(Visualizer.getCaptureSizeRange()[1]);capture.setDataCaptureListener(new Visualizer.OnDataCaptureListener(){public void onWaveFormDataCapture(Visualizer v,byte[] b,int r){}public void onFftDataCapture(Visualizer v,byte[] b,int r){fft=b.clone();reactive=true;}},Math.min(20000,Visualizer.getMaxCaptureRate()),false,true);capture.setEnabled(true);}catch(Exception e){reactive=false;capture=null;}}
